	/** This control prevents replacing the single-page cache with an unbounded cache of every visited page. */
	@ParameterizedTest(name = "order={0}, managed snapshot={1}")
	@CsvSource({ "spoc,false", "spoc,true", "opsc,false", "opsc,true" })
	void nodeFirstCacheEvictsPagesOutsideItsBoundedWorkingSet(String order, boolean managed) throws Exception {
		int predicates = 32;
		try (Fixture fixture = new Fixture(directory, sharedRows(predicates, 2), true); Txn txn = fixture.snapshot()) {
			assertThat(physicalEntries(fixture.adjacency.pagesDbi(), txn, order)).isEqualTo(predicates);
			long[] unbound = { -1, -1, -1, -1 };
			try (ReadWork work = new ReadWork()) {
				assertThat(read(fixture, txn, managed, order, unbound, null))
						.containsExactlyElementsOf(expected(fixture.quads, order, unbound, null));
				assertThat(work.pageDecodes)
						.as("a later node revisits pages evicted by more than sixteen independent predicates: %s", work)
						.isGreaterThan(predicates);
			}
		}
	}

	@ParameterizedTest(name = "incoming={0}, explicit={1}")
	@CsvSource({ "false,true", "true,true", "false,false", "true,false" })
	void nodeOnlyCountsUsePersistedDirectoryCardinalities(boolean incoming, boolean explicit) throws Exception {
		List<Quad> seed = new ArrayList<>();
		for (int predicate = 0; predicate < 2; predicate++) {
			for (int ordinal = 0; ordinal < LmdbPersistentAdjacency.PAGE_QUADS; ordinal++) {
				seed.add(nodeQuad(incoming, FIRST_PREDICATE + predicate, ordinal, ordinal % 3 == 0 ? 7 : 0));
			}
		}
		seed.add(new Quad(90_000, FIRST_PREDICATE, 90_001, 7));
		try (Fixture fixture = new Fixture(directory, seed, explicit)) {
			fixture.store.startTransaction();
			for (long predicate = FIRST_PREDICATE; predicate < FIRST_PREDICATE + 2; predicate++) {
				fixture.remove(nodeQuad(incoming, predicate, 0, 7));
				fixture.add(nodeQuad(incoming, predicate, 1, 7));
				fixture.add(nodeQuad(incoming, predicate, LmdbPersistentAdjacency.PAGE_QUADS + 1, 0));
			}
			Quad oppositePlane = nodeQuad(incoming, FIRST_PREDICATE, 20_000, 7);
			assertThat(fixture.store.storeTriple(oppositePlane.subject(), oppositePlane.predicate(),
					oppositePlane.object(), oppositePlane.context(), !explicit)).isTrue();
			fixture.store.commit();
			long subject = incoming ? -1 : BOUND_NODE;
			long object = incoming ? BOUND_NODE : -1;
			long expected = fixture.quads.stream()
					.filter(quad -> incoming ? quad.object() == BOUND_NODE : quad.subject() == BOUND_NODE)
					.count();
			assertThat(expected).isEqualTo(2L * (LmdbPersistentAdjacency.PAGE_QUADS + 1));
			try (Txn txn = fixture.snapshot()) {
				long stamp = txn.lockManager().readLock();
				try (ReadWork work = new ReadWork()) {
					assertThat(fixture.adjacency.count(txn.get(), subject, -1, object, -1, explicit))
							.isEqualTo(expected);
					assertAll(
							() -> assertThat(work.pageDecodes)
									.as("node-only counts must not decode statement pages: %s", work)
									.isZero(),
							() -> assertThat(work.nativeReads.operations().getOrDefault("mdb_cursor_open", 0L))
									.as("one contiguous node/predicate directory scan is sufficient: %s", work)
									.isLessThanOrEqualTo(1),
							() -> assertThat(work.nativeReads.operations().getOrDefault("mdb_cursor_get", 0L))
									.as("directory work scales with two predicates, not thousands of neighbors: %s",
											work)
									.isLessThanOrEqualTo(4));
				} finally {
					txn.lockManager().unlockRead(stamp);
				}
			}
		}
	}

	private static Quad nodeQuad(boolean incoming, long predicate, int ordinal, long context) {
		long neighbor = 10_000 + ordinal;
		return new Quad(incoming ? neighbor : BOUND_NODE, predicate, incoming ? BOUND_NODE : neighbor, context);
	}

	private static List<Quad> sharedRows(int predicates, int rows) {
		List<Quad> seed = new ArrayList<>();
		for (int ordinal = 0; ordinal < rows; ordinal++) {
			for (int predicate = 0; predicate < predicates; predicate++) {
				seed.add(sharedQuad(ordinal, FIRST_PREDICATE + predicate));
			}
		}
		return seed;
	}

	private static Quad sharedQuad(int ordinal, long predicate) {
		return new Quad(100 + 2L * ordinal, predicate, 10_000 + 2L * ordinal, ordinal % 3 == 0 ? 7 : 0);
	}

	private static List<Quad> read(Fixture fixture, Txn txn, boolean managed, String order, long[] pattern, long[] seek)
			throws Exception {
		if (managed) {
			try (RecordIterator records = fixture.adjacency.scan(txn, pattern[0], pattern[1], pattern[2], pattern[3],
					fixture.explicit, order)) {
				return collect(records, seek);
			}
		}
		long stamp = txn.lockManager().readLock();
		try (RecordIterator records = fixture.adjacency.scan(txn.get(), pattern[0], pattern[1], pattern[2], pattern[3],
				fixture.explicit, order)) {
			return collect(records, seek);
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static List<Quad> collect(RecordIterator records, long[] seek) {
		if (seek != null) {
			assertThat(records.seekForward(seek[0], seek[1], seek[2], seek[3])).isTrue();
		}
		List<Quad> result = new ArrayList<>();
		long[] quad;
		while ((quad = records.next()) != null) {
			result.add(new Quad(quad[0], quad[1], quad[2], quad[3]));
		}
		return result;
	}

	private static List<Quad> expected(List<Quad> quads, String order, long[] pattern, long[] seek) {
		Comparator<Quad> comparator = (left, right) -> {
			for (char field : order.toCharArray()) {
				int compared = Long.compareUnsigned(left.component(field), right.component(field));
				if (compared != 0) {
					return compared;
				}
			}
			return 0;
		};
		Quad minimum = seek == null ? null : new Quad(seek[0], seek[1], seek[2], seek[3]);
		return quads.stream()
				.filter(quad -> (pattern[0] == -1 || pattern[0] == quad.subject())
						&& (pattern[1] == -1 || pattern[1] == quad.predicate())
						&& (pattern[2] == -1 || pattern[2] == quad.object())
						&& (pattern[3] == -1 || pattern[3] == quad.context())
						&& (minimum == null || comparator.compare(quad, minimum) >= 0))
				.sorted(comparator)
				.toList();
	}

	private static long physicalEntries(int database, Txn txn, String order) throws Exception {
		long stamp = txn.lockManager().readLock();
		try (MemoryStack stack = MemoryStack.stackPush()) {
			int plane = order.equals("opsc") ? 1 : 0;
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_cursor_open(txn.get(), database, handle));
			long cursor = handle.get(0);
			try {
				MDBVal key = MDBVal.malloc(stack);
				MDBVal value = MDBVal.malloc(stack);
				long count = 0;
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result != MDB_NOTFOUND) {
					E(result);
					ByteBuffer bytes = key.mv_data();
					if (bytes.get(0) == plane) {
						count++;
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				return count;
			} finally {
				mdb_cursor_close(cursor);
			}
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private record Quad(long subject, long predicate, long object, long context) {
		long[] array() {
			return new long[] { subject, predicate, object, context };
		}

		long component(char field) {
			return switch (field) {
			case 's' -> subject;
			case 'p' -> predicate;
			case 'o' -> object;
			case 'c' -> context;
			default -> throw new AssertionError(field);
			};
		}
	}

